/*
 * docker-logconfig.js translates the docker json-file log options stored
 * in the 'docker:logconfig' internal_metadata key into the zoneadmd(8) log
 * rotation settings used by vmadm (zlog_max_size, zlog_keep_rotated).
 *
 * The input is user-controlled, so nothing here throws: invalid options
 * are reported in 'errors' and simply produce no setting.
 */

var assert = require('/usr/node/node_modules/assert-plus');

/* Largest integer a JS Number holds exactly (Number.MAX_SAFE_INTEGER). */
var MAX_SAFE_INTEGER = 9007199254740991;

/* zoneadmd keeps at most this many rotated logs (ZLOG_KEEP_MAX). */
var ZLOG_KEEP_MAX = 1000;

/* docker max-size: positive integer with optional k/m/g (powers of 1000) */
var MAX_SIZE_RE = /^([0-9]+)([kmg]?)$/;
var MAX_SIZE_MULTIPLIER = {'': 1, k: 1000, m: 1000000, g: 1000000000};

/* docker max-file: positive integer */
var MAX_FILE_RE = /^[0-9]+$/;

/* The input is user controlled; it may define its own 'hasOwnProperty'. */
var hasOwn = Function.prototype.call.bind(Object.prototype.hasOwnProperty);

/* docker:logconfig options and the vmadm properties derived from them. */
var LOGCONFIG_OPTS = {
    'max-size': {prop: 'zlog_max_size', convert: maxSizeToBytes},
    'max-file': {prop: 'zlog_keep_rotated', convert: maxFileToKeep}
};

/**
 * Returns the option value as a string if it is a string or a number,
 * otherwise undefined.
 *
 * @param {*} value - raw option value from the parsed logconfig
 * @returns {String|undefined}
 */
function optString(value) {
    if (typeof (value) === 'string' || typeof (value) === 'number') {
        return String(value);
    }
    return undefined;
}

/**
 * Converts a docker max-size value to bytes.
 *
 * @param {String} value - e.g. '30m', '1000', '2g'
 * @returns {Number|undefined} bytes, or undefined if invalid or too large
 */
function maxSizeToBytes(value) {
    var m = MAX_SIZE_RE.exec(value);
    var bytes;

    if (m === null) {
        return undefined;
    }

    bytes = Number(m[1]) * MAX_SIZE_MULTIPLIER[m[2]];
    if (bytes < 1 || bytes > MAX_SAFE_INTEGER) {
        return undefined;
    }

    return bytes;
}

/**
 * Converts a docker max-file value to a zoneadmd rotated-log count.
 *
 * docker's max-file counts the live log, zoneadmd counts only rotated
 * logs, so keep = max-file - 1. zoneadmd treats 0 as "keep all", so the
 * result is never below 1 and never above ZLOG_KEEP_MAX. For max-file=1,
 * this keeps one rotated log plus the live log (two files total); zoneadmd
 * cannot keep zero rotated logs because 0 disables pruning.
 *
 * @param {String} value - e.g. '3'
 * @returns {Number|undefined} count in [1, 1000], or undefined if invalid
 */
function maxFileToKeep(value) {
    if (!MAX_FILE_RE.test(value) || Number(value) < 1) {
        return undefined;
    }

    return Math.min(ZLOG_KEEP_MAX, Math.max(1, Number(value) - 1));
}

/**
 * Translates a 'docker:logconfig' JSON string into zlog settings.
 *
 * @param {String} logconfig - JSON object string, e.g.
 *     '{"max-file":"3","max-size":"30m"}'
 * @returns {Object} result
 * @returns {Number} [result.zlog_max_size] - from max-size, in bytes
 * @returns {Number} [result.zlog_keep_rotated] - from max-file
 * @returns {String[]} [result.absent] - properties whose option is missing
 *     from a valid logconfig object (unset when the logconfig is invalid)
 * @returns {String[]} result.errors - one message per ignored option
 */
function zlogFromLogConfig(logconfig) {
    var cfg;
    var result = {errors: []};

    assert.string(logconfig, 'logconfig');

    try {
        cfg = JSON.parse(logconfig);
    } catch (e) {
        result.errors.push('docker:logconfig is not valid JSON');
        return result;
    }

    if (cfg === null || typeof (cfg) !== 'object' || Array.isArray(cfg)) {
        result.errors.push('docker:logconfig is not a JSON object');
        return result;
    }

    result.absent = [];
    Object.keys(LOGCONFIG_OPTS).forEach(function _opt(opt) {
        var prop = LOGCONFIG_OPTS[opt].prop;
        var value;

        if (!hasOwn(cfg, opt)) {
            result.absent.push(prop);
            return;
        }

        value = optString(cfg[opt]);
        value = (value === undefined)
            ? undefined : LOGCONFIG_OPTS[opt].convert(value);
        if (value === undefined) {
            result.errors.push('invalid ' + opt + ' in docker:logconfig');
        } else {
            result[prop] = value;
        }
    });

    return result;
}

/**
 * Returns the zlog properties a create/update payload implies through
 * 'docker:logconfig', for a docker VM using the json-file log driver.
 *
 * - A valid option sets its property.
 * - A missing max-file option (including a removed logconfig) uses the
 *   smallest bounded retention value. A missing max-size option leaves the
 *   current size cap unchanged.
 * - An invalid option or logconfig is reported in 'errors'. An update leaves
 *   existing properties unchanged; a create still gets default retention.
 * - A property set explicitly in the payload is never derived.
 *
 * @param {Object} payload - create/update payload
 * @param {Object|null} vmobj - existing VM on update, null on create
 * @param {String} log_driver - effective docker log driver
 * @returns {Object} result
 * @returns {Object} result.props - property values to merge into payload
 * @returns {String[]} result.errors - why options were ignored
 */
function zlogPropsForPayload(payload, vmobj, log_driver) {
    var driver_changed;
    var md;
    var md_key;
    var removed;
    var result = {props: {}, errors: []};
    var stored_keep;
    var transitioning;
    var zlog;

    assert.object(payload, 'payload');
    assert.optionalObject(vmobj, 'vmobj');

    if (!(payload.docker || (vmobj && vmobj.docker))
        || log_driver !== 'json-file') {

        return result;
    }

    md_key = vmobj ? 'set_internal_metadata' : 'internal_metadata';
    driver_changed = vmobj && vmobj.internal_metadata
        && hasOwn(vmobj.internal_metadata, 'docker:logdriver')
        && vmobj.internal_metadata['docker:logdriver'] !== 'json-file'
        && ((payload[md_key]
        && hasOwn(payload[md_key], 'docker:logdriver'))
        || (Array.isArray(payload.remove_internal_metadata)
        && payload.remove_internal_metadata.indexOf('docker:logdriver')
        !== -1));
    transitioning = vmobj && ((!vmobj.docker && payload.docker)
        || driver_changed);
    if (payload[md_key] && hasOwn(payload[md_key], 'docker:logconfig')) {
        md = payload[md_key];
    }

    if (md !== undefined) {
        if (typeof (md['docker:logconfig']) !== 'string') {
            result.errors.push('docker:logconfig is not a string');
            if (vmobj && !transitioning) {
                return result;
            }
        } else {
            zlog = zlogFromLogConfig(md['docker:logconfig']);
            result.errors = zlog.errors;
            if (zlog.absent === undefined && vmobj && !transitioning) {
                /* unparseable update: leave existing properties unchanged */
                return result;
            }
        }
    } else {
        removed = Array.isArray(payload.remove_internal_metadata)
            && payload.remove_internal_metadata.indexOf('docker:logconfig')
                !== -1;
        if (!removed && !transitioning && vmobj) {
            return result;
        }
        if (transitioning && !removed
            && !(vmobj.zlog_keep_rotated > 0)
            && vmobj.internal_metadata
            && typeof (vmobj.internal_metadata['docker:logconfig'])
                === 'string') {

            zlog = zlogFromLogConfig(
                vmobj.internal_metadata['docker:logconfig']);
            stored_keep = zlog.zlog_keep_rotated;
            result.errors = zlog.errors;
            zlog = undefined;
        }
    }

    Object.keys(LOGCONFIG_OPTS).forEach(function _derive(opt) {
        var prop = LOGCONFIG_OPTS[opt].prop;

        if (hasOwn(payload, prop)) {
            return;
        }
        if (zlog && zlog[prop] !== undefined) {
            result.props[prop] = zlog[prop];
        } else if (prop === 'zlog_keep_rotated'
            && stored_keep !== undefined) {

            result.props[prop] = stored_keep;
        } else if (prop === 'zlog_keep_rotated' && transitioning
            && vmobj.zlog_keep_rotated > 0 && !removed
            && (md === undefined || !zlog || !zlog.absent
                || zlog.absent.indexOf(prop) === -1)) {

            /* A driver change must not narrow existing safe retention. */
            return;
        } else if (prop === 'zlog_keep_rotated'
            && (!vmobj || transitioning || !zlog
                || (zlog.absent && zlog.absent.indexOf(prop) !== -1))) {

            result.props[prop] = 1;
        }
    });

    return result;
}

module.exports = {
    zlogFromLogConfig: zlogFromLogConfig,
    zlogPropsForPayload: zlogPropsForPayload
};
